// §19 WF04 — บันทึกนัดหมาย + คำนวณเวลาเตือน (T-24h, T-2h) ใน static data ของ workflow
const body = ($json.body && typeof $json.body === 'object') ? $json.body : ($json || {});
const sd = $getWorkflowStaticData('global');
sd.appointments = Array.isArray(sd.appointments) ? sd.appointments : [];
const s = (v, m) => (v === null || v === undefined) ? '' : String(v).trim().slice(0, m);
const startRaw = body.startAt || body.start_at || body.datetime;
const startAt = startRaw ? new Date(startRaw) : null;
if (!startAt || isNaN(startAt.getTime())) {
  return [{ json: { ok: false, error: 'ต้องระบุ startAt (ISO date) หรือ datetime', saved: false } }];
}
const id = s(body.appointmentId || body.id, 64) || ('apt-' + startAt.getTime());
const rec = { id, title: s(body.title, 160) || 'นัดหมายลูกค้า', prospectId: body.prospectId || null,
  name: s(body.name, 120) || null, phone: s(body.phone, 30) || null, agent: s(body.agent || body.assignee, 80) || null,
  channel: s(body.channel, 30) || 'onsite', startAt: startAt.toISOString(),
  reminders: [ { kind: 'T-24h', at: new Date(startAt.getTime() - 24 * 3600e3).toISOString(), sent: false },
               { kind: 'T-2h', at: new Date(startAt.getTime() - 2 * 3600e3).toISOString(), sent: false } ],
  status: 'scheduled', note: s(body.note, 500) || null, createdAt: new Date().toISOString() };
const i = sd.appointments.findIndex(a => a.id === id);
if (i >= 0) sd.appointments[i] = rec; else sd.appointments.push(rec);
if (sd.appointments.length > 200) sd.appointments = sd.appointments.slice(-200);
return [{ json: { ok: true, saved: true, action: i >= 0 ? 'updated' : 'created', appointment: rec,
  pendingReminders: rec.reminders.length, total: sd.appointments.length } }];

// หานัดที่ถึงเวลาเตือนแล้ว (และยังไม่เคยเตือน)
const sd = $getWorkflowStaticData('global');
sd.appointments = Array.isArray(sd.appointments) ? sd.appointments : [];
const now = Date.now();
const due = [];
for (const a of sd.appointments) {
  if (a.status === 'done' || a.status === 'cancelled') continue;
  for (const r of (a.reminders || [])) {
    if (r.sent) continue;
    const t = new Date(r.at).getTime();
    if (t <= now) { due.push({ appointmentId: a.id, kind: r.kind, title: a.title, name: a.name, phone: a.phone,
      agent: a.agent, startAt: a.startAt, prospectId: a.prospectId, channel: a.channel, note: a.note }); r.sent = true; }
  }
}
return [{ json: { dueCount: due.length, due, total: sd.appointments.length, at: new Date().toISOString() } }];

const log = $json || {};
const src = $('หานัดที่ถึงเวลาเตือน').first().json;
return [{ json: { ok: true, remindersSent: src.dueCount, taskId: log.taskId || null, email: log.email || null,
  at: new Date().toISOString() } }];
